17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.ArrayList;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
27	import org.springframework.samples.petclinic.rest.advice.InvalidFieldsException;
28	import org.springframework.samples.petclinic.rest.advice.RequiredFieldsMissingException;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.util.StringUtils;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	    }
78	
79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    /**
105	     * Rejects an owner payload that is missing or blank in any required field. The response body's
106	     * {@code errors} array lists the name of each offending field.
107	     *
108	     * @param ownerFieldsDto the owner payload to validate
109	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
110	     */
111	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
112	        List<String> missingFields = new ArrayList<>();
113	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
114	            missingFields.add("firstName");
115	        }
116	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
117	            missingFields.add("lastName");
118	        }
119	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
120	            missingFields.add("address");
121	        }
122	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
123	            missingFields.add("city");
124	        }
125	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
126	            missingFields.add("telephone");
127	        }
128	        if (!missingFields.isEmpty()) {
129	            throw new RequiredFieldsMissingException(missingFields);
130	        }
131	    }
132	
133	    /**
134	     * Normalizes a telephone number by removing every non-digit character and requires the
135	     * result to be exactly 10 digits.
136	     *
137	     * @param telephone the raw telephone value from the request
138	     * @return the 10-digit, digits-only telephone
139	     * @throws InvalidFieldsException if the stripped value is not exactly 10 digits
140	     */
141	    private String normalizeTelephone(String telephone) {
142	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
143	        if (digits.length() != 10) {
144	            throw new InvalidFieldsException(List.of("telephone"));
145	        }
146	        return digits;
147	    }
148	
149	    /**
150	     * Rejects a telephone that, once normalized, is already used by any existing owner. Existing
151	     * owners' telephones are normalized the same way before comparison so differently-formatted
152	     * values representing the same number are treated as duplicates.
153	     *
154	     * @param telephone the normalized (digits-only) telephone of the owner being created
155	     * @throws DuplicateOwnerTelephoneException if another owner already uses the telephone
156	     */
157	    private void requireUniqueTelephone(String telephone) {
158	        boolean taken = this.clinicService.findAllOwners().stream()
159	            .map(Owner::getTelephone)
160	            .filter(existing -> existing != null)
161	            .map(existing -> existing.replaceAll("\\D", ""))
162	            .anyMatch(telephone::equals);
163	        if (taken) {
164	            throw new DuplicateOwnerTelephoneException(telephone);
165	        }
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
171	        validateRequiredFields(ownerFieldsDto);
172	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
173	        requireUniqueTelephone(telephone);
174	        HttpHeaders headers = new HttpHeaders();
175	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
176	        owner.setTelephone(telephone);
177	        this.clinicService.saveOwner(owner);
178	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
179	        headers.setLocation(UriComponentsBuilder.newInstance()
180	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
181	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
187	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
188	        if (currentOwner == null) {
189	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	        }
191	        currentOwner.setAddress(ownerFieldsDto.getAddress());
192	        currentOwner.setCity(ownerFieldsDto.getCity());
193	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
194	        currentOwner.setLastName(ownerFieldsDto.getLastName());
195	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
196	        this.clinicService.saveOwner(currentOwner);
197	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
198	    }
199	
200	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
201	    @Transactional
202	    @Override
203	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
204	        Owner owner = this.clinicService.findOwnerById(ownerId);
205	        if (owner == null) {
206	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
207	        }
208	        this.clinicService.deleteOwner(owner);
209	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
210	    }
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
215	        Owner owner = this.clinicService.findOwnerById(ownerId);
216	        if (owner == null) {
217	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
218	        }
219	        HttpHeaders headers = new HttpHeaders();
220	        Pet pet = petMapper.toPet(petFieldsDto);
221	        owner.setId(ownerId);
222	        pet.setOwner(owner);
223	        pet.getType().setName(null);
224	        this.clinicService.savePet(pet);
225	        PetDto petDto = petMapper.toPetDto(pet);
226	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
227	            .buildAndExpand(pet.getId()).toUri());
228	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
229	    }
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
233	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
234	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
235	        if (currentOwner != null) {
236	            Pet currentPet = this.clinicService.findPetById(petId);
237	            if (currentPet != null) {
238	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
239	                currentPet.setName(petFieldsDto.getName());
240	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
241	                this.clinicService.savePet(currentPet);
242	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
243	            }
244	        }
245	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
246	    }
247	
248	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
249	    @Override
250	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
251	        HttpHeaders headers = new HttpHeaders();
252	        Visit visit = visitMapper.toVisit(visitFieldsDto);
253	        Pet pet = new Pet();
254	        pet.setId(petId);
255	        visit.setPet(pet);
256	        this.clinicService.saveVisit(visit);
257	        VisitDto visitDto = visitMapper.toVisitDto(visit);
258	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
259	            .buildAndExpand(visit.getId()).toUri());
260	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
261	    }
262	
263	
264	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
265	    @Override
266	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
267	        Owner owner = this.clinicService.findOwnerById(ownerId);
268	        if (owner != null) {
269	            Pet pet = owner.getPet(petId);
270	            if (pet != null) {
271	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
272	            }
273	        }
274	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
275	    }
276	}
